      "coreTheory": "1. 암묵지 vs 형식지 특성 비교:\n   - 암묵지 (Tacit Knowledge): 개인의 경험, 직관, 손맛에 내재된 지식. 언어나 기호로 표현하기 어렵고 타인이 쉽게 모방할 수 없어 조직의 독보적 경쟁 우위 원천이 됨.\n   - 형식지 (Explicit Knowledge): 매뉴얼, 서적, 코드 등 기호와 문서로 객관화된 지식. 지식의 전달성과 공유성이 매우 높음.\n2. SECI 4단계 변환 나선:\n   - 사회화 (Socialization): 암묵지 → 암묵지 (도제식 교육, 선배의 기술을 곁에서 관찰하고 현장 경험 공유).\n   - 표출화 (Externalization): 암묵지 → 형식지 (개인의 경험과 노하우를 매뉴얼, 문서, 다이어그램으로 공식화).\n   - 연결화 (Combination): 형식지 → 형식지 (기존 문서와 데이터들을 편집, 종합하여 새로운 체계적 매뉴얼 수립).\n   - 내면화 (Internalization): 형식지 → 암묵지 (문서화된 매뉴얼을 반복 실습·훈련하여 개인의 몸에 완벽히 체화).",
