      "comparisonTable": null,
      "coreTheory": "1. 개체 무결성 (Entity Integrity):\n   - 테이블의 기본키(Primary Key)는 각 튜플(행)을 고유하게 식별해야 하므로, 결코 NULL 값을 가질 수 없으며 중복될 수 없음.\n2. 참조 무결성 (Referential Integrity):\n   - 외래키(Foreign Key) 값은 참조하는 부모 릴레이션의 기본키 값과 반드시 일치하거나, 부모가 존재하지 않는 경우 NULL이어야 함.\n   - 부모 테이블에 없는 엉뚱한 값을 외래키에 저장할 수 없음.\n3. 도메인 무결성 (Domain Integrity):\n   - 테이블의 특정 속성(컬럼) 값은 사전에 정의된 데이터 타입, 길이, 허용 가능한 유효 값의 범위(Domain) 내에 속해야 함 (예: 나이 컬럼에 음수나 문자 입력 불가).",
