      "coreTheory": "1. 개념적 데이터 모델링 (Conceptual Modeling):\n   - 사용자의 업무 요구사항을 분석하여 핵심 엔터티(Entity)와 주요 관계를 도출하고 최상위 ER 다이어그램을 작성함.\n   - 전사적 데이터 구조를 한눈에 파악하는 고수준 추상화 단계.\n2. 논리적 데이터 모델링 (Logical Modeling):\n   - 개념 모델을 바탕으로 모든 속성(Attribute), 기본키/외래키를 확정하고, 중복을 제거하는 정규화(Normalization)를 철저히 수행함.\n   - 특정 DBMS 하드웨어에 종속되지 않는 독립적인 이상적 스키마 설계.\n3. 물리적 데이터 모델링 (Physical Modeling):\n   - 실제 도입할 특정 DBMS(Oracle, MySQL 등)의 성능 특성, 인덱스, 테이블스페이스, 파티셔닝을 고려하여 물리적 저장 구조를 설계함.\n   - 조회 성능 향상을 위해 필요 시 고의로 중복을 허용하는 반정규화(De-normalization)를 적용함.",
      "metaphor": "건축 설계 3단계: 우리 집은 방 3개 거실 1개로 하겠다는 전체 조감도(개념) → 철근과 배관 규격을 완벽히 맞춘 표준 청사진 도면(논리) → 실제 콘크리트 타설과 자재 발주(물리).",
      "analogy": "건축 설계 3단계: 우리 집은 방 3개 거실 1개로 하겠다는 전체 조감도(개념) → 철근과 배관 규격을 완벽히 맞춘 표준 청사진 도면(논리) → 실제 콘크리트 타설과 자재 발주(물리).",
      "trapsAndTips": "- 🚨 단골 함정: 정규화(Normalization)는 물리적 모델링 단계에서 수행한다? → 오답! 정규화는 '논리적 데이터 모델링' 단계의 핵심 과업입니다.\n- 📌 1초 암기 공식: 개념(ERD) → 논리(정규화/속성) → 물리(DBMS/반정규화)!",
