      "coreTheory": "1. ERP (Enterprise Resource Planning, 전사적 자원 관리):\n   - 기업의 인사, 재무, 회계, 생산, 구매, 판매 등 모든 경영 자원과 업무 프로세스를 하나의 통합된 데이터베이스로 관리하여 전사 최적화를 달성함.\n2. CRM (Customer Relationship Management, 고객 관계 관리):\n   - 신규 고객 유치, 기존 고객 유지, 고객 이탈 방지 및 고객 생애 가치(LTV)를 극대화하기 위해 고객의 모든 접점 데이터를 통합 분석하는 경영 전략 시스템.\n3. SCM (Supply Chain Management, 공급망 관리):\n   - 원자재 공급업체부터 제조공장, 물류창고, 유통업체, 최종 소비자에 이르는 공급 사슬 전체의 물동량과 정보를 통합 관리하여 재고를 최소화하고 납기를 단축함.",
      "metaphor": "자동차 공장: 부품 구매비와 직원 월급을 관리하는 중앙 회계 시스템(ERP) + 자동차를 산 차주에게 정기 엔진오일 교환 쿠폰을 보내는 관리 시스템(CRM) + 타이어와 철판을 제시간에 공장에 배달시키는 물류망(SCM).",
      "analogy": "자동차 공장: 부품 구매비와 직원 월급을 관리하는 중앙 회계 시스템(ERP) + 자동차를 산 차주에게 정기 엔진오일 교환 쿠폰을 보내는 관리 시스템(CRM) + 타이어와 철판을 제시간에 공장에 배달시키는 물류망(SCM).",
