      "coreTheory": "1. 가명처리 (Pseudonymization):\n   - 개인 식별 속성을 다른 가명이나 식별 불가능한 코드로 대체 (예: 홍길동 → 임꺽정, 김철수 → User_A).\n2. 총계처리 (Aggregation):\n   - 개별 레코드 값을 숨기고 총합, 평균 등 통계 요약값으로 일괄 변환 (예: 개별 급여 숨기고 '팀 전체 평균 연봉 5,000만원'으로 표기).\n3. 데이터 삭제 (Data Suppression):\n   - 주민등록번호, 상세 집주소 등 식별성이 매우 높은 주요 컬럼이나 특정 레코드 자체를 아예 잘라내어 삭제.\n4. 데이터 범주화 (Data Bucketing):\n   - 구체적인 수치를 대략적인 범주나 연령대, 구간으로 묶음 (예: 34세 → 30대, 연봉 4,200만원 → 4,000~5,000만원 구간).\n5. 데이터 마스킹 (Data Masking):\n   - 데이터의 특정 민감한 자리수를 별표(*)나 특수기호로 덮어 가림 (예: 900101-1******, hong***@naver.com).",
