      "coreTheory": "1. 상향식 접근법 (Bottom-Up):\n   - 가설을 먼저 세우지 않고, 수집된 데이터 자체를 출발점으로 삼아 데이터 속의 숨겨진 상관관계, 유사성, 군집을 귀납적(Inductive)으로 발굴함.\n2. 핵심 기법: 비지도학습 (Unsupervised Learning):\n   - 정답(Label)이 주어지지 않은 상태에서 데이터의 구조적 특성을 파악함.\n   - 군집분석 (Clustering): 유사한 특성을 가진 고객들을 세분화 군집으로 분류.\n   - 연관분석 (Association): 장바구니에서 함께 팔리는 상품 간의 연관규칙 마이닝.\n   - 주성분 분석 (PCA): 상관성이 높은 변수들을 소수의 주성분으로 축약.",
