      "coreTheory": "1. 준비도 (Readiness):\n   - 기업의 분석 인력, 분석 기법, IT 인프라, 데이터 문화 등 분석을 수행할 준비가 얼마나 갖추어졌는지를 평가.\n2. 성숙도 (Maturity):\n   - 조직 내에서 분석이 실제로 얼마나 고도화되어 비즈니스 성과 창출에 활용되고 있는지를 평가.\n3. 4분면 포지셔닝 진단:\n   - 도입형 (준비도 낮음, 성숙도 낮음): 기초 인프라와 분석 인력 확보가 최우선 과제.\n   - 확산형 (준비도 높음, 성숙도 낮음): 최신 시스템과 인프라는 갖추었으나 전사적 활용도가 미진함.\n   - 정착형 (준비도 낮음, 성숙도 높음): 시스템 인프라는 열악하나 일부 실무 부서 중심으로 뛰어난 성과를 냄.\n   - 준비형 (준비도 높음, 성숙도 높음): 인프라와 활용 역량이 모두 전사적으로 성숙한 가장 이상적인 데이터 주도 조직.",
