      "coreTheory": "1. 결측값 처리 3대 전략:\n   - 완전자료 분석법 (Complete Case Analysis): 결측치가 하나라도 있는 행을 통째로 삭제 (`na.omit()`). 정보 손실이 커 표본 크기가 작을 때 치명적.\n   - 단순 대치법 (Single Imputation):\n     - 평균 대치법 (Mean Imputation): 해당 변수의 평균값으로 결측치를 채움.\n     - 중앙값 대치법 (Median Imputation): 이상치가 심할 때 유용.\n     - 최빈값 대치법 (Mode Imputation): 범주형 변수에 적용.\n   - 다중 대치법 (Multiple Imputation):\n     - 대치(Imputation) → 분석(Analysis) → 결합(Pooling)의 3단계를 거쳐 결측치 불확실성을 반영하는 가장 이상적인 통계 기법 (R의 `Amelia`, `mice` 패키지).\n\n2. ★평균 대치법의 치명적 문제점 (시험 단골):\n   - 가운데 평균 위치로 수많은 데이터가 몰려버리기 때문에, 데이터의 흩어진 정도를 나타내는 분산(Variance)이 실제보다 작아지는 '분산 과소추정(Underestimation of Variance)' 현상이 발생함!",
