      "coreTheory": "1. 이상치(Outlier)의 정의:\n   - 대부분의 데이터가 모여 있는 군집 범위에서 비정상적으로 극단적으로 멀리 떨어져 있는 관측치.\n\n2. 사분위수 범위 (IQR: Interquartile Range):\n   - 데이터를 크기순으로 나열했을 때 상위 25% 지점(Q3)에서 하위 25% 지점(Q1)을 뺀 구간 길이.\n   - `IQR = Q3 - Q1` (전체 데이터의 가운데 50%가 위치하는 구간)\n\n3. ★Tukey의 사분위수 이상치 판별 공식 (상자수염 그림 Boxplot):\n   - 하한 안쪽 울타리 (Lower Fence): $Q1 - 1.5 \\times IQR$\n   - 상한 안쪽 울타리 (Upper Fence): $Q3 + 1.5 \\times IQR$\n   - 판정: 관측값 $X < Q1 - 1.5 \\times IQR$ 이거나 $X > Q3 + 1.5 \\times IQR$ 이면 이상치로 분류!\n   - (참고: $3.0 \\times IQR$를 넘어가면 극단적 이상치 Extreme Outlier).",
