      "coreTheory": "1. 첨도(Kurtosis)의 정의:\n   - 데이터 분포의 중심 정점(Peak)이 얼마나 뾰족한지, 그리고 꼬리 부분(Tail)이 얼마나 두꺼운지를 나타내는 척도.\n\n2. 기준값 판정 (표준정규분포 기준):\n   - 정규분포의 첨도 = 3:\n     - 정규첨 (Mesokurtic): 표준정규분포와 동일한 뾰족함.\n   - 첨도 > 3 (양의 초과 첨도):\n     - 급첨 (Leptokurtic): 정규분포보다 중심이 더 뾰족하고, 양쪽 꼬리가 두꺼움(Heavy-tailed). 금융 시장의 급격한 폭락/폭등 위험(Fat-tail)을 모델링할 때 나타남.\n   - 첨도 < 3 (음의 초과 첨도):\n     - 완첨 (Platykurtic): 정규분포보다 정점이 더 완만하고 평평하며, 꼬리가 얇음.\n\n*(참고: 통계 패키지에 따라 정규분포 첨도를 0으로 맞추기 위해 '첨도 - 3'으로 정의하는 초과 첨도(Excess Kurtosis)를 쓰기도 함).*",
