      "diagram": null,
      "comparisonTable": null,
      "coreTheory": "셀 수 있는(이산형) 확률변수가 따르는 대표 분포 4가지입니다.\n\n| 분포명 | 정의 및 핵심 매개변수 | 평균 ($E(X)$) | 분산 ($V(X)$) | 실제 활용 예시 |\n| :--- | :--- | :--- | :--- | :--- |\n| 베르누이 분포 | 결과가 성공(1) 또는 실패(0) 2가지만 나오는 1회 시행 ($p$) | $p$ | $p(1-p)$ | 동전 1번 던지기, 암 발병 여부 |\n| 이항분포 (Binomial) | 베르누이 시행을 독립적으로 $n$번 반복했을 때 성공 횟수 $X$ ($n, p$) | $np$ | $np(1-p)$ | 동전을 100번 던져 앞면이 나온 횟수 |\n| 포아송 분포 (Poisson) | 단위 시간이나 단위 면적당 매우 드물게 발생하는 사건의 발생 횟수 ($\\lambda$) | $\\lambda$ | $\\lambda$ (평균=분산 동일!) | 1시간 동안 콜센터에 걸려오는 전화 수, 책 한 페이지당 오타 수 |\n| 기하분포 (Geometric) | 독립 베르누이 시행에서 처음으로 성공할 때까지 시도한 횟수(또는 실패 횟수) | $\\frac{1}{p}$ | $\\frac{1-p}{p^2}$ | 양궁 선수가 10점을 맞출 때까지 쏜 화살 수 |",
