      "coreTheory": "모집단의 참값인 모수($\\theta$)를 단 하나의 숫자로 추정할 때, 그 추정량($\\hat{\\theta}$)이 갖추어야 할 바람직한 4가지 성질입니다.\n\n1. 불편성 (Unbiasedness, 편향 없음):\n   - 추정량의 기댓값이 참 모수와 정확히 일치하는 성질: $E(\\hat{\\theta}) = \\theta$.\n   - 체계적인 과대/과소 추정 왜곡(편향)이 없음.\n2. 효율성 (Efficiency, 유효성):\n   - 여러 불편추정량 중에서 분산(Variance)이 가장 작은 성질.\n   - 분산이 작을수록 추정값이 모수 주변에 촘촘하게 모여 있어 믿을 수 있음 (최소분산 불편추정량 MVUE).\n3. 일치성 (Consistency):\n   - 표본의 크기 $n$이 무한히 커질수록, 추정량이 참 모수로 확률적으로 수렴하는 성질.\n4. 충분성 (Sufficiency):\n   - 표본이 가지고 있는 모수에 대한 모든 유용한 정보를 그 추정량이 완벽하게 담고 있는 성질.",
