      "coreTheory": "1. 구간추정 (Interval Estimation):\n   - 모수가 포함될 것으로 기대되는 범위 [하한값, 상한값]와 그 신뢰수준(Confidence Level)을 함께 제시하는 추정 방법.\n\n2. ★95% 신뢰구간의 정확한 해석 (시험 단골 함정):\n   - 옳은 해석: 같은 크기의 표본을 독립적으로 100번 반복 추출하여 각 표본마다 95% 신뢰구간을 100개 계산했을 때, 그 100개의 구간 중 대략 95개 구간이 고정된 참 모수를 포함한다는 의미.\n   - 틀린 해석 (오답 선지):\n     - ❌ \"모수가 이 구간 안에 속할 확률이 95%이다\" (모수는 움직이지 않는 고정된 상수이므로 확률이 아닌 0 아니면 1임).\n     - ❌ \"모든 데이터의 95%가 이 구간에 들어있다.\"\n\n3. 신뢰구간 길이와 신뢰수준:\n   - 신뢰수준을 높일수록(95% → 99%) 신뢰구간의 길이는 더 넓어집니다 (정확성은 떨어짐).\n   - 표본 크기 $n$을 키울수록 표준오차가 줄어들어 신뢰구간 길이는 더 좁고 정밀해집니다.",
      "metaphor": "신뢰구간은 바다에 던지는 그물입니다. 고래(모수)는 가만히 있고 그물(신뢰구간)을 100번 던졌을 때 95번은 고래를 잡고 5번은 헛스윙한다는 뜻이지, 고래가 그물 속에서 95% 확률로 헤엄친다는 뜻이 아닙니다.",
      "analogy": "신뢰구간은 바다에 던지는 그물입니다. 고래(모수)는 가만히 있고 그물(신뢰구간)을 100번 던졌을 때 95번은 고래를 잡고 5번은 헛스윙한다는 뜻이지, 고래가 그물 속에서 95% 확률로 헤엄친다는 뜻이 아닙니다.",
