      "coreTheory": "연속형 변수의 평균 차이를 비교하는 3대 t-검정입니다.\n\n| t-검정 유형 | 비교 대상 | 독립성 여부 | 실제 분석 사례 | R 문법 |\n| :--- | :--- | :--- | :--- | :--- |\n| 단일표본 t-검정 (One-sample) | 1개 표본 집단의 평균 vs 특정 기준값($\\mu_0$) | 단일 집단 | 과자 1봉지 무게가 표기된 100g과 같은가? | `t.test(x, mu = 100)` |\n| 독립표본 t-검정 (Two-sample Independent) | 서로 완전히 독립된 두 집단의 평균 차이 | 독립 | 남학생 집단과 여학생 집단의 수학 성적 비교 | `t.test(score ~ gender)` |\n| ★대응표본 t-검정 (Paired t-test) | 동일한 대상(피험자)의 사전(Pre) vs 사후(Post) 차이 비교 | 종속 (쌍을 이룸) | 다이어트 약 복용 전 몸무게 vs 복용 후 몸무게 비교 | `t.test(pre, post, paired = TRUE)` |\n\n- 대응표본의 핵심: 개체 간의 편차(원래 뚱뚱한 사람과 마른 사람)를 제거하기 위해 개인별 변화량($D = Post - Pre$)의 평균이 0인지를 검정함!",
