      "coreTheory": "1. 분산분석 (ANOVA: Analysis of Variance):\n   - 3개 이상의 독립된 집단 간 평균 차이를 검정하는 통계 기법.\n   - (왜 t-검정을 여러 번 안 쓰나? t-검정을 3번 반복하면 제1종 오류가 눈덩이처럼 누적 증가하므로 ANOVA로 한 번에 검정!).\n\n2. ★F-검정 통계량의 원리 (F-ratio):\n   $$F = \\frac{\\text{집단 간 분산 (Between Variance, 처리제곱합)}}{\\text{집단 내 분산 (Within Variance, 오차제곱합)}} = \\frac{MSB}{MSW}$$\n   - 집단 간 분산: 서로 다른 처치/그룹 때문에 생긴 차이 (신호).\n   - 집단 내 분산: 집단 내부 개별 사람들의 우연한 오차 (노이즈).\n   - 판정: $F$ 값이 커서 $p < 0.05$이면 \"적어도 한 집단의 평균은 나머지 집단과 다르다!\"\n\n3. 사후검정 (Post-Hoc Test):\n   - ANOVA에서 귀무가설이 기각되었을 때, \"도대체 어떤 집단과 어떤 집단 간에 진짜 차이가 나는가?\"를 구체적으로 밝히기 위한 추가 검정 (Tukey HSD, Scheffe, Bonferroni 등).",
      "metaphor": "A, B, C 세 학교의 수학 실력을 비교할 때, 학교 간 평균 격차(집단 간 분산)가 같은 학교 안에서 학생들끼리 점수가 들쭉날쭉한 정도(집단 내 분산)보다 훨씬 압도적으로 커야 비로소 '학교 간 실력 차이가 진짜 난다(F값 큼)'고 인정받습니다.",
      "analogy": "A, B, C 세 학교의 수학 실력을 비교할 때, 학교 간 평균 격차(집단 간 분산)가 같은 학교 안에서 학생들끼리 점수가 들쭉날쭉한 정도(집단 내 분산)보다 훨씬 압도적으로 커야 비로소 '학교 간 실력 차이가 진짜 난다(F값 큼)'고 인정받습니다.",
      "trapsAndTips": "F값 공식의 분자와 분모를 바꾼 선지가 단골입니다! 분자가 '집단 간(Between)', 분모가 '집단 내(Within)'입니다. 또한 ANOVA 결과 기각되었을 때 구체적인 집단 간 차이를 밝히기 위해 실시하는 것은 '사후검정(Post-hoc test)'입니다.",
