      "coreTheory": "1. 변수 선택 3대 알고리즘:\n   - 전진선택법 (Forward Selection):\n     - 절편만 있는 빈 모형에서 시작하여, 가장 유의미한 변수를 하나씩 차례대로 추가.\n     - 단점: 한 번 들어간 변수는 나중에 중요도가 떨어져도 절대 제거되지 않음.\n   - 후진제거법 (Backward Elimination):\n     - 모든 독립변수가 포함된 풀(Full) 모형에서 시작하여, 가장 기여도가 낮은 변수를 하나씩 제거.\n     - 단점: 변수 수가 표본 수보다 많으면 적용 불가하며, 한 번 빠진 변수는 다시 들어올 수 없음.\n   - 단계적 방법 (Stepwise Method - 가장 널리 사용):\n     - 전진선택과 후진제거를 결합하여, 새 변수를 추가할 때 기존 변수의 유의성을 재검토하여 불필요해진 변수를 제거하는 양방향 탐색!\n\n2. ★모형 적합도 기준 (AIC & BIC) - 초특급 빈출:\n   - AIC (Akaike Information Criterion) & BIC (Bayesian Information Criterion):\n     - 모형의 적합도(우도)와 모형의 복잡도(변수 개수 페널티)를 함께 반영한 지표.\n     - 판정 기준: AIC 또는 BIC 값은 무조건 작을수록(Smallest is Best) 최적의 모형!\n     - BIC는 표본 크기($n$)를 반영하므로 AIC보다 변수 개수에 대해 더 가혹한 벌점(Penalty)을 부과함.",
