      "coreTheory": "시간의 흐름에 따라 관측된 시계열 데이터를 미래 예측에 활용하기 위해 가장 먼저 확보해야 하는 핵심 통계적 성질입니다.\n\n1. 정상 시계열의 3대 조건 (무조건 암기):\n   - 조건 1: 평균(Mean)이 일정하다:\n     - 시간 $t$의 흐름에 따라 평균이 상승하거나 하강하는 추세(Trend)가 없이 수평축 주변에 머물러야 함: $E(X_t) = \\mu$.\n   - 조건 2: 분산(Variance)이 일정하다:\n     - 시간에 따라 데이터의 진폭이나 변동성이 커지거나 작아지지 않고 일정해야 함: $Var(X_t) = \\sigma^2$.\n   - 조건 3: 공분산(Covariance)은 특정 시점($t$)이 아니라 오직 시차(Lag, $k$)에만 의존한다:\n     - $Cov(X_t, X_{t+k}) = \\gamma_k$ (시점 $t$가 1990년이든 2020년이든 상관없이, 두 관측치 사이의 시간 간격 $k$에 의해서만 공분산이 결정됨).\n\n2. 정상 시계열의 시각적 형태:\n   - 어떤 임의의 시간 구간을 잘라보아도 평균선 주변에서 일정 폭으로 끊임없이 진동하며 평균으로 회귀(Mean Reversion)하는 성질을 보임.",
