      "coreTheory": "1. 시계열 3대 모형의 개념:\n   - AR 모형 (자기회귀, AutoRegressive): 현시점의 값을 자신의 과거 관측치들의 선형 결합으로 설명 ($X_t = c + \\phi_1 X_{t-1} + \\dots + \\epsilon_t$).\n   - MA 모형 (이동평균, Moving Average): 현시점의 값을 과거의 예측 오차(White Noise)들의 선형 결합으로 설명 ($X_t = \\mu + \\epsilon_t - \\theta_1 \\epsilon_{t-1} - \\dots$).\n   - ARIMA(p, d, q) 모형: 비정상 시계열을 $d$번 차분하여 정상화한 후 $AR(p)$와 $MA(q)$를 결합한 통합 모형. ($d=0$이면 ARMA).\n\n2. ★ACF(자기상관함수) & PACF(부분자기상관함수) 판별 규칙 (시험 100% 출제):\n   | 모형 | ACF (자기상관함수) 패턴 | PACF (부분자기상관함수) 패턴 |\n   | :--- | :--- | :--- |\n   | $AR(p)$ 모형 | 지수적으로 서서히 감소 (점근적 감쇄) | 시차 $p$ 이후에 0으로 뚝 끊김 (절단 Cut-off) |\n   | $MA(q)$ 모형 | 시차 $q$ 이후에 0으로 뚝 끊김 (절단 Cut-off) | 지수적으로 서서히 감소 (점근적 감쇄) |\n   | $ARMA(p, q)$ 모형 | 둘 다 시차 0 이후 서서히 감쇄 | 둘 다 서서히 감쇄 |",
