      "oneLiner": "오즈 = p/(1-p), 로짓 = ln(오즈), 회귀계수 β의 의미: 독립변수 X가 1단위 증가할 때 오즈는 exp(β)배 증가!",
      "diagram": null,
      "comparisonTable": null,
      "coreTheory": "종속변수가 연속형이 아니라 이항 범주형(성공 1 vs 실패 0)일 때 사용하는 대표적인 확률 분류 알고리즘입니다.\n\n1. 오즈 (Odds, 승산):\n   - 실패 확률 대비 성공 확률의 비율:\n     $$\\text{Odds} = \\frac{p}{1 - p} \\quad (0 \\le \\text{Odds} < \\infty)$$\n\n2. 로짓 변환 (Logit Transformation):\n   - 오즈에 자연로그를 취하여 범위를 $(-\\infty, +\\infty)$로 확장시켜 선형회귀식과 연결:\n     $$\\ln\\left(\\frac{p}{1 - p}\\right) = \\beta_0 + \\beta_1 X$$\n\n3. 시그모이드 함수 (Sigmoid / Logistic Function):\n   - 로짓 식을 확률 $p$에 대해 풀면 $S$자 곡선 형태의 함수 도출:\n     $$p = \\frac{1}{1 + e^{-(\\beta_0 + \\beta_1 X)}}$$\n\n4. ★오즈비 (Odds Ratio)와 회귀계수의 해석 (시험 100% 출제):\n   - 독립변수 $X$가 1단위 증가할 때 성공 오즈는 $\\exp(\\beta_1) = e^{\\beta_1}$배 증가함!\n   - 예: $\\beta_1 = 0.693$이면 $e^{0.693} \\approx 2$이므로, \"$X$가 1 증가할 때 합격 오즈는 2배가 된다.\"",
