      "coreTheory": "1. 혼동 행렬 (Confusion Matrix):\n   - TP (True Positive): 실제 1을 1로 정확히 예측 (암 환자를 암으로 진단)\n   - TN (True Negative): 실제 0을 0으로 정확히 예측 (정상인을 정상으로 진단)\n   - FP (False Positive, 제1종 오류): 실제 0인데 1로 오판 (정상인을 암으로 오진)\n   - FN (False Negative, 제2종 오류): 실제 1인데 0으로 오판 (암 환자를 정상으로 놓침)\n\n2. ★핵심 성능 지표 공식 (무조건 암기):\n   - 정확도 (Accuracy): $\\frac{TP + TN}{TP + TN + FP + FN}$ (불균형 데이터에서는 왜곡 심함).\n   - 정밀도 (Precision): $\\frac{TP}{TP + FP}$ (모델이 1이라고 예측한 것 중 진짜 1의 비율).\n   - 재현율 (Recall / Sensitivity 민감도): $\\frac{TP}{TP + FN}$ (실제 1인 것들 중 모델이 맞춘 비율).\n   - 특이도 (Specificity): $\\frac{TN}{TN + FP}$ (실제 0인 것들 중 모델이 맞춘 비율).\n   - F1-Score: 정밀도와 재현율의 조화평균 = $2 \\times \\frac{\\text{Precision} \\times \\text{Recall}}{\\text{Precision} + \\text{Recall}}$\n\n3. ★ROC 곡선과 AUC (Area Under Curve):\n   - X축: $1 - \\text{특이도}$ (FPR = 위양성률)\n   - Y축: $\\text{민감도}$ (TPR = 재현율)\n   - 왼쪽 상단 모서리에 바짝 붙을수록 우수하며, 곡선 아래 면적인 AUC 값이 1에 가까울수록 완벽한 모델 (0.5는 무작위 동전 던지기).",
