      "coreTheory": "1. 군집분석 (Clustering - 비지도학습):\n   - K-Means 군집: 군집 중심점(Centroid)을 지정된 $K$개만큼 배치하고 거리 기반으로 반복 갱신. 이상치에 취약.\n   - 계층적 군집의 와드 연결법 (Ward's Method): 군집 간 결합 시 생기는 오차제곱합의 증가량(정보 손실)을 최소화하는 방향으로 병합.\n   - 실루엣 계수 (Silhouette): 군집 내 응집도와 군집 간 분리도를 동시에 평가. $-1 \\le s \\le +1$ (1에 가까울수록 완벽한 군집화).\n\n2. ★연관성 분석 3대 지표 (장바구니 분석 - 시험 100% 출제):\n   - 1. 지지도 (Support): 전체 거래 중 $A$와 $B$가 동시에 구매된 거래의 비율:\n     $$\\text{Support}(A \\rightarrow B) = P(A \\cap B) = \\frac{\\text{A와 B 동시 거래 수}}{\\text{전체 거래 수}}$$\n   - 2. 신뢰도 (Confidence): 품목 $A$를 구매했을 때 품목 $B$도 함께 구매할 조건부 확률:\n     $$\\text{Confidence}(A \\rightarrow B) = P(B | A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{\\text{A와 B 동시 거래 수}}{\\text{A 거래 수}}$$\n   - 3. 향상도 (Lift): $A$를 샀을 때 $B$를 사는 확률이, $B$ 혼자 팔릴 확률보다 몇 배나 증가했는가:\n     $$\\text{Lift}(A \\rightarrow B) = \\frac{\\text{Confidence}(A \\rightarrow B)}{P(B)} = \\frac{P(A \\cap B)}{P(A) \\times P(B)}$$\n     - $\text{Lift} > 1$: 양의 상관관계 (함께 구매할 가능성이 매우 높음, 연관성 있음!).\n     - $\text{Lift} = 1$: 서로 완전 독립 (아무 연관 없음).\n     - $\text{Lift} < 1$: 음의 상관관계 (서로 배척함, 대체재).",
